async function oneSimulation(e,p,rows,{capture=false,quiet=false,seed=1}={}){loadFireForEvent(e,p,rows);if(!G.centers.length)throw Error('No selected ignition on burnable cells for event '+e.id);G.tbs=Math.max(1,Math.round(p.tb/p.dt));G.tbMax=G.tbs*3;resetState(p.seedR);const count=G.act.length;if(capture&&rec&&G.im)vframe(0);const nS=Math.ceil(e.hours*60/p.dt),per=Math.max(1,Math.round(10/p.dt));let tm=0;
 let currentSegment=-1;for(let k=0;k<nS&&running;k++){const segment=Math.floor(k*p.dt/(240*60));if(segment!==currentSegment){currentSegment=segment;const offset=segment*240;await loadMet(p,{...e,start:e.start+offset*36e5,hours:Math.min(240,e.hours-offset)});note('INFO',`Event ${e.id}: weather segment ${segment+1}, hours ${offset}–${Math.min(e.hours,offset+240)}`)}step(p,k*p.dt-segment*240*60);tm=(k+1)*p.dt;if((k+1)%per===0||k===nS-1||!G.act.length){if(G.im){drawFrame();if(capture&&rec){vframe(tm);await sleep(35)}if(!quiet){record(tm);log(`Event ${e.id}: t + ${(tm/60).toFixed(1)} h; ${H.area.at(-1)} km² burnt/burning.`,`घटना ${e.id}: t + ${(tm/60).toFixed(1)} घंटे; ${H.area.at(-1)} किमी² जला/जल रहा है।`);await raf()}}if(!G.act.length)break}}
 const mask=new Uint8Array(G.N);for(let i=0;i<G.N;i++)if(G.state[i]===1||G.state[i]===2)mask[i]=1;return{mask,centers:[...G.centers],ignited:count,elapsed:tm/60}}
