async function multiRun(){const b=$('mrun');let oldIm,oldState,oldAge;try{const p=P();assertPrepared(p);if(!G.refs.some(r=>r?.has))throw Error('No clear satellite reference for ROC/PR.');setCandidate({moist:p.moist,rain:p.rainK});const n=clamp(Number($('nrun').value)||10,10,30),cnt=new Uint16Array(G.N),cntValid=new Uint16Array(G.N);b.disabled=true;running=true;oldIm=G.im;oldState=G.state.slice();oldAge=G.age.slice();G.im=null;const rows=HROWS.slice();for(let run=0;run<n&&running;run++){const union=new Uint8Array(G.N),validUnion=new Uint8Array(G.N);for(let j=0;j<lastPlan.length;j++){const m=(await oneSimulation(lastPlan[j],p,rows,{quiet:true,seed:run+1})).mask;for(let i=0;i<G.N;i++){union[i]|=m[i];if(G.refs[j]?.has)validUnion[i]|=m[i]}}for(let i=0;i<G.N;i++){cnt[i]+=union[i];cntValid[i]+=validUnion[i]}log(`Ensemble ${run+1}/${n}…`,`अनेक रन ${run+1}/${n}…`);await raf()}
 if(!running)throw Error('Ensemble stopped.');G.prob=Float32Array.from(cnt,v=>v/n);G.probValid=Float32Array.from(cntValid,v=>v/n);const{ref,valid}=referenceUnion(),pos=new Float64Array(n+1),neg=new Float64Array(n+1);let brier=0,total=0;for(let i=0;i<G.N;i++)if(valid[i]&&G.inside[i]&&!NF[G.lc[i]]){(ref[i]?pos:neg)[cntValid[i]]++;brier+=(cntValid[i]/n-ref[i])**2;total++}
 const Ppos=pos.reduce((a,x)=>a+x,0),Nneg=neg.reduce((a,x)=>a+x,0);if(!Ppos||!Nneg)throw Error('Reference needs both burnt and unburnt valid cells for ROC and PR.');let tp=0,fp=0,auc=0,ap=0,px=0,py=0,pr=0;const roc=[{x:0,y:0}],prec=[{x:0,y:1}];for(let k=n;k>=0;k--){tp+=pos[k];fp+=neg[k];const tpr=tp/Ppos,fpr=fp/Nneg,precision=tp/Math.max(1,tp+fp);auc+=(fpr-px)*(tpr+py)/2;ap+=(tpr-pr)*precision;px=fpr;py=tpr;pr=tpr;roc.push({x:fpr,y:tpr});prec.push({x:tpr,y:precision})}
 MR.forEach(c=>c?.destroy());function curve(id,title,data,xlab,ylab){return new Chart($(id),{type:'scatter',data:{datasets:[{label:title,data,showLine:true,borderColor:'#ff7a00',pointRadius:0,borderWidth:2}]},options:{responsive:true,maintainAspectRatio:false,animation:false,plugins:{title:{display:true,text:title}},scales:{x:{min:0,max:1,title:{display:true,text:xlab}},y:{min:0,max:1,title:{display:true,text:ylab}}}}})}MR=[curve('c4',`ROC · AUC ${auc.toFixed(3)}`,roc,'False positive rate','True positive rate'),curve('c5',`PR · AP ${ap.toFixed(3)}`,prec,'Recall','Precision')];translateCharts();newChart('c7','Confusion matrix (whole area)',['TP','FP','FN','TN'],['TP','FP','FN','TN'].map(k=>G.validationRows?.[0][1][k]||0),'#ad2224');$('mrres').textContent=tr(`${n} runs · AUC ${auc.toFixed(3)} · AP ${ap.toFixed(3)} · Brier ${(brier/total).toFixed(4)}`,`${n} रन · AUC ${auc.toFixed(3)} · AP ${ap.toFixed(3)} · Brier ${(brier/total).toFixed(4)}`);
 SC.push(['validation','ensemble','AUC',auc],['validation','ensemble','AP',ap],['validation','ensemble','Brier score',brier/total]);ART.validation={...(ART.validation||{}),raster:G.prob,plots:['c6','c4','c5','c7'],scores:SC.filter(r=>r[0]==='validation')};drawBG();validate();ART.validation.raster=G.prob;ART.validation.plots=['c6','c4','c5','c7'];ART.validation.scores=SC.filter(r=>r[0]==='validation');renderExports();openStep('resultsSection')}
 catch(e){log('Error: '+e.message)}finally{G&&(G.im=oldIm||G.im,G.state=oldState||G.state,G.age=oldAge||G.age);running=false;b.disabled=false}}
