/* Sensitivity and held-out event calibration; identical random stream per candidate. */
function seeded(n){let x=n|0;return()=>((x=Math.imul(x,1664525)+1013904223|0)>>>0)/4294967296}
function renderTrainEvents(){const box=$('trainEvents');box.replaceChildren();if(!SELR.size)return;const p=document.createElement('p');p.textContent=tr('Training ranges (unchecked ranges are held out for testing):','प्रशिक्षण रेंज (बिना चुनी रेंज परीक्षण के लिए अलग):');box.append(p);[...SELR].sort((a,b)=>a-b).forEach((k,j)=>{const l=document.createElement('label');l.className='row';const c=document.createElement('input');c.type='checkbox';c.className='trainEvent';c.dataset.id=String(k+1);c.checked=j<Math.max(1,Math.floor(SELR.size/2));l.append(c,document.createTextNode(`${k+1}. ${RNG[k].a} – ${RNG[k].b}`));box.append(l)})}
function setCandidate(q){RAIN_K=q.rain;updateBase(q.moist)}
async function evaluateCandidate(q,indices,rows){const p={...P(),R0:q.R0,tb:q.tb};setCandidate(q);let total=0,number=0,means=[];for(const j of indices){const e=lastPlan[j],r=G.refs[j];if(!r?.has)continue;RAND=seeded(101+j);const m=(await oneSimulation(e,p,rows,{quiet:true})).mask,ref=new Uint8Array(G.N);for(let i=0;i<G.N;i++)if(r.valid[i])ref[i]=r.bx[i]>Number($('bthr').value)*1e4?1:0;const s=calcScores(m,ref,r.valid,clamp(Number($('tol').value)||0,0,2));if(Number.isFinite(s.F1)){total+=s.F1;number++;means.push(s.F1)}}RAND=Math.random;return number?{mean:total/number,individual:means}:null}
$('sensitivity').onclick=async()=>{const b=$('sensitivity');let im,st,age;try{const p=P();assertPrepared(p);const valid=lastPlan.map((_,j)=>j).filter(j=>G.refs[j]?.has);if(!valid.length)throw Error('At least one event needs clear pre/post burn reference.');running=true;b.disabled=true;im=G.im;st=G.state.slice();age=G.age.slice();G.im=null;const base={R0:p.R0,tb:p.tb,moist:Number($('moist').value)||.8,rain:Number($('rainK').value)||.1},sens=[];for(const key of ['R0','tb','moist','rain'])for(const f of [.75,1,1.25]){const q={...base,[key]:clamp(base[key]*f,key==='moist'?.05:.001,key==='moist'?1:1000)},s=await evaluateCandidate(q,valid,HROWS);sens.push([key,f,s?.mean??NaN]);log(`Sensitivity ${key} × ${f}: ${s?.mean?.toFixed(3)||'N/A'}`,`संवेदनशीलता ${key} × ${f}: ${s?.mean?.toFixed(3)||'उपलब्ध नहीं'}`);await raf()}
 sensitivityDone=true;G.sensitivity=sens;newChart('c9','Sensitivity · F1 by parameter and multiplier',sens.map(x=>x[0]+' ×'+x[1]),sens.map(x=>x[2]),'#45a8cb');ART.calibration={raster:null,plots:['c9'],scores:sens.map(x=>['calibration','sensitivity',x[0]+' × '+x[1],x[2]])};SC.push(...ART.calibration.scores);renderExports();openStep('validationSection')}
 catch(e){log('Error: '+e.message)}finally{if(G){G.im=im||G.im;G.state=st||G.state;G.age=age||G.age;updateBase(Number($('moist').value)||.8);RAIN_K=Number($('rainK').value)||.1}RAND=Math.random;running=false;b.disabled=false}}
$('calibrate').onclick=async()=>{const b=$('calibrate');let im,st,age;try{const p=P();assertPrepared(p);if(!sensitivityDone)throw Error('Run sensitivity before calibration.');const train=new Set([...document.querySelectorAll('.trainEvent:checked')].map(el=>+el.dataset.id)),trainIdx=lastPlan.map((e,j)=>train.has(e.id)?j:-1).filter(j=>j>=0),testIdx=lastPlan.map((e,j)=>!train.has(e.id)?j:-1).filter(j=>j>=0);if(!trainIdx.length||!testIdx.length||[...trainIdx,...testIdx].some(j=>!G.refs[j]?.has))throw Error('Need clear reference for at least one training and one held-out event.');running=true;b.disabled=true;im=G.im;st=G.state.slice();age=G.age.slice();G.im=null;
 const original={R0:p.R0,tb:p.tb,moist:Number($('moist').value)||.8,rain:Number($('rainK').value)||.1},firstTrain=await evaluateCandidate(original,trainIdx,HROWS),firstTest=await evaluateCandidate(original,testIdx,HROWS);let best={...original},bestScore=firstTrain?.mean??-1;for(const key of ['R0','tb','moist','rain']){let choice=best[key];for(const mul of [.6,1,1.4]){const q={...best,[key]:clamp(best[key]*mul,key==='moist'?.05:.001,key==='moist'?1:1000)},out=await evaluateCandidate(q,trainIdx,HROWS);if((out?.mean??-1)>bestScore){bestScore=out.mean;choice=q[key]}}best[key]=choice;note('INFO',`Calibration ${key}=${choice.toFixed(3)}, training F1=${bestScore.toFixed(3)}`)}const afterTrain=await evaluateCandidate(best,trainIdx,HROWS),afterTest=await evaluateCandidate(best,testIdx,HROWS);
 $('r0').value=best.R0.toFixed(3);$('tb').value=best.tb.toFixed(2);$('moist').value=best.moist.toFixed(3);$('rainK').value=best.rain.toFixed(3);setCandidate(best);
 newChart('c8','Calibration before / after F1',['Train before','Train after','Held-out before','Held-out after'],[firstTrain?.mean,afterTrain?.mean,firstTest?.mean,afterTest?.mean],'#d95639');$('calres').textContent=tr(`Training F1 ${firstTrain?.mean?.toFixed(3)} → ${afterTrain?.mean?.toFixed(3)}; held-out F1 ${firstTest?.mean?.toFixed(3)} → ${afterTest?.mean?.toFixed(3)}. R₀ ${best.R0.toFixed(2)}, burn ${best.tb.toFixed(1)} min, moisture ${best.moist.toFixed(3)}, rain ${best.rain.toFixed(3)}.`,`प्रशिक्षण F1 ${firstTrain?.mean?.toFixed(3)} → ${afterTrain?.mean?.toFixed(3)}; अलग परीक्षण F1 ${firstTest?.mean?.toFixed(3)} → ${afterTest?.mean?.toFixed(3)}। R₀ ${best.R0.toFixed(2)}, जलने का समय ${best.tb.toFixed(1)} मिनट, नमी ${best.moist.toFixed(3)}, वर्षा ${best.rain.toFixed(3)}।`);
 const rows=[['calibration','train','before_F1',firstTrain.mean],['calibration','train','after_F1',afterTrain.mean],['calibration','test','before_F1',firstTest.mean],['calibration','test','after_F1',afterTest.mean],...Object.entries(best).map(([k,v])=>['calibration','parameter',k,v])];SC.push(...rows);
 // A separate calibrated union raster, with the calibrated event weather and rules.
 const union=new Uint8Array(G.N);for(const e of lastPlan){const out=await oneSimulation(e,{...p,R0:best.R0,tb:best.tb},HROWS,{quiet:true});for(let i=0;i<G.N;i++)union[i]|=out.mask[i]}
 ART.calibration={raster:union,plots:['c8','c9'],scores:SC.filter(r=>r[0]==='calibration')};if($('vid').checked){G.im=im;phase='calibration';vstart();for(const event of lastPlan)await oneSimulation(event,{...p,R0:best.R0,tb:best.tb},HROWS,{quiet:true,capture:true});await vstop();G.im=null}note('OK','Calibration finished; held-out metrics computed without fitting those events.');renderExports();openStep('resultsSection')}
 catch(e){log('Error: '+e.message)}finally{if(G){G.im=im||G.im;G.state=st||G.state;G.age=age||G.age}RAND=Math.random;running=false;b.disabled=false}}
/* Client-side baseline GeoTIFF: IEEE float32 with WGS84 GeoKeys and cell tie point. */
function geotiff(values){if(!G||!values||values.length!==G.N)throw Error('No raster to export.');const n=G.N,dataBytes=n*4,entries=[],extra=[];let extraBytes=0;
 const put=(tag,type,count,value)=>entries.push({tag,type,count,value}),append=(buf)=>{const offset=extraBytes;extra.push(buf);extraBytes+=(buf.byteLength+1)&~1;return offset};
 put(256,4,1,G.nx);put(257,4,1,G.ny);put(258,3,1,32);put(259,3,1,1);put(262,3,1,1);put(273,4,1,0);put(277,3,1,1);put(278,4,1,G.ny);put(279,4,1,dataBytes);put(284,3,1,1);put(339,3,1,3);
 const scale=new Float64Array([G.dx,G.dy,0]),tie=new Float64Array([0,0,0,G.w,G.n,0]),geo=new Uint16Array([1,1,0,3,1024,0,1,2,1025,0,1,1,2048,0,1,4326]);put(33550,12,3,append(scale.buffer));put(33922,12,6,append(tie.buffer));put(34735,3,geo.length,append(geo.buffer));entries.sort((a,b)=>a.tag-b.tag);
 const ifd=8,tableBytes=2+entries.length*12+4,extraStart=ifd+tableBytes,pixelsStart=extraStart+extraBytes,buf=new ArrayBuffer(pixelsStart+dataBytes),dv=new DataView(buf);dv.setUint16(0,0x4949,true);dv.setUint16(2,42,true);dv.setUint32(4,ifd,true);dv.setUint16(ifd,entries.length,true);
 entries.find(x=>x.tag===273).value=pixelsStart;for(let i=0;i<entries.length;i++){const e=entries[i],off=ifd+2+i*12;dv.setUint16(off,e.tag,true);dv.setUint16(off+2,e.type,true);dv.setUint32(off+4,e.count,true);if(e.count*(e.type===12?8:e.type===3?2:4)<=4){if(e.type===3)dv.setUint16(off+8,e.value,true);else dv.setUint32(off+8,e.value,true)}else dv.setUint32(off+8,extraStart+e.value,true)}dv.setUint32(ifd+2+entries.length*12,0,true);
 let at=extraStart;for(const arr of extra){new Uint8Array(buf,at,arr.byteLength).set(new Uint8Array(arr));at+=(arr.byteLength+1)&~1}
 for(let i=0;i<n;i++)dv.setFloat32(pixelsStart+i*4,G.inside[i]?Number(values[i]):NaN,true);return new Blob([buf],{type:'image/tiff'})}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function csvBlob(rows){const escape=x=>'"'+String(x??'').replaceAll('"','""')+'"';return new Blob(['phase,scope,metric,value\n'+rows.map(r=>r.map(escape).join(',')).join('\n')+'\n'],{type:'text/csv;charset=utf-8'})}
function plotPng(ids){const canvases=ids.map(id=>$(id)).filter(c=>c instanceof HTMLCanvasElement&&c.width&&c.height),width=Math.max(600,...canvases.map(x=>x.width)),height=45+canvases.reduce((n,x)=>n+x.height+12,0),out=document.createElement('canvas');out.width=width;out.height=height;const c=out.getContext('2d');c.fillStyle='#13191d';c.fillRect(0,0,width,height);c.fillStyle='#fff';c.font='18px sans-serif';c.fillText('Wildfire simulator · '+new Date().toISOString().slice(0,10),10,27);let y=45;for(const src of canvases){c.drawImage(src,0,y,src.width,src.height);y+=src.height+12}return new Promise((resolve,reject)=>out.toBlob(b=>b?resolve(b):reject(Error('PNG canvas export failed.')),'image/png'))}
function renderExports(){const box=$('exports');box.replaceChildren();for(const [stage,en,hi]of [['simulation','Simulation','सिमुलेशन'],['validation','Validation','सत्यापन'],['calibration','Calibration','कैलिब्रेशन']]){const item=ART[stage],set=document.createElement('fieldset'),legend=document.createElement('legend');legend.textContent=tr(en,hi);set.append(legend);const grid=document.createElement('div');grid.className='grid';for(const [kind,english,hindi]of [['raster','Raster (.tif)','रास्टर (.tif)'],['video','Video (.webm)','वीडियो (.webm)'],['plots','Plots (.png)','ग्राफ (.png)'],['scores','Scores (.csv)','स्कोर (.csv)']]){const b=document.createElement('button');b.textContent=tr(english,hindi);b.disabled=!item?.[kind]||Array.isArray(item[kind])&&!item[kind].length;b.onclick=async()=>{try{if(kind==='raster')downloadBlob(geotiff(item.raster),stage+'.tif');else if(kind==='video')downloadBlob(item.video,stage+'.webm');else if(kind==='plots')downloadBlob(await plotPng(item.plots),stage+'-plots.png');else downloadBlob(csvBlob(item.scores),stage+'-scores.csv')}catch(e){log('Error: '+e.message)}};grid.append(b)}set.append(grid);box.append(set)}}
